#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -d "$APP" ]] || APP="$ROOT"

V44="$APP/bottom-nav-flush-v44.js"
V51="$APP/native-ai-sheet-v51.js"

for f in "$V44" "$V51"; do
  [[ -f "$f" ]] || { echo "ERROR: missing $f"; exit 1; }
done

DIR="$APP/.memeflow-patches/floating-ai-step1-clean-v2"
mkdir -p "$DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"

V44_BAK="$DIR/bottom-nav-flush-v44.js.$STAMP.bak"
V51_BAK="$DIR/native-ai-sheet-v51.js.$STAMP.bak"
V44_WORK="$DIR/bottom-nav-flush-v44.js.$STAMP.work.js"
V51_WORK="$DIR/native-ai-sheet-v51.js.$STAMP.work.js"
PY="$DIR/install.$STAMP.py"
REPORT="$DIR/report.$STAMP.txt"

cp "$V44" "$V44_BAK"
cp "$V51" "$V51_BAK"
cp "$V44" "$V44_WORK"
cp "$V51" "$V51_WORK"

rollback(){
  cp "$V44_BAK" "$V44" 2>/dev/null || true
  cp "$V51_BAK" "$V51" 2>/dev/null || true
  rm -f "$V44_WORK" "$V51_WORK" "$PY"
}
trap 'echo "ERROR: FLOATING AI STEP 1 failed; restoring exact pre-install files."; rollback' ERR

printf '%s' '' | base64 -d > "$PY"
python3 "$PY" "$V44_WORK" "$V51_WORK" | tee "$REPORT"

node --check "$V44_WORK" >/dev/null
node --check "$V51_WORK" >/dev/null

cp "$V44_WORK" "$V44"
cp "$V51_WORK" "$V51"

cat > "$DIR/latest-manifest.txt" <<EOF
V44=$V44
V51=$V51
V44_BACKUP=$V44_BAK
V51_BACKUP=$V51_BAK
REPORT=$REPORT
EOF

rm -f "$V44_WORK" "$V51_WORK" "$PY"
trap - ERR

echo
echo "OK: FLOATING AI STEP 1 CLEAN V2 installed."
echo "No duplicate AI control and no new CSS owner were added."
echo "Stop -> Run, then hard-refresh Safari."
